///|
async fn server_is_running(state : Json) -> Bool {
  let script = server_probe_script()
  let running = remote(state, script, "orca-server-probe").trim() == "101"
  save_diagnostic(
    "orca-server-probe",
    if running {
      "ready"
    } else {
      "not-running"
    },
  )
  running
}

///|
fn server_probe_script() -> String {
  let script =
    #|curl --disable --noproxy '*' --silent --max-time 2 --output /dev/null --write-out '%{http_code}' \
    #|  --header 'Connection: Upgrade' --header 'Upgrade: websocket' \
    #|  --header 'Sec-WebSocket-Version: 13' \
    #|  --header 'Sec-WebSocket-Key: REDACTED' \
    #|  http://127.0.0.1:47121/ || true
  script
}

///|
async fn reserve_server_port(state : Json) -> Int32 {
  match field(state, "localPort") {
    Some(Json::Number(value, ..)) => value.to_int()
    _ => {
      let listener = @socket.TcpServer::TcpServer(
        @socket.Addr::parse("127.0.0.1:0"),
      )
      let port = listener.addr.port()
      listener.close()
      set_field(state, "localPort", Json::number(port.to_double()))
      port
    }
  }
}

///|
async fn ssh_args(
  state : Json,
  services~ : Bool = true,
  lease~ : String = "",
) -> Array[String] {
  [
    "-o",
    "BatchMode=yes",
    "-o",
    "ConnectTimeout=15",
    "-o",
    "ProxyCommand=" + proxy(state, adapter_executable(), services~, lease~),
    "-o",
    "StrictHostKeyChecking=no",
    "-o",
    "UserKnownHostsFile=/dev/null",
    "-o",
    "LogLevel=ERROR",
    required(state, "user") + "@" + required(state, "workspaceId") + ".devsy",
  ]
}

///|
async fn remote(state : Json, script : String, stage : String) -> String {
  command("ssh", ssh_args(state, services=false) + [script], stage)
}

///|
fn up_result(output : String) -> Json raise {
  let results = []
  for line in output.split("\n") {
    if line.trim() != "" {
      let parsed = @json.parse(line.to_owned())
      if field(parsed, "kind") == Some(Json::string("result")) {
        results.push(parsed)
      }
    }
  }
  guard results.length() == 1 &&
    field(results[0], "outcome") == Some(Json::string("success")) else {
    raise AdapterError(
      "Devsy did not return exactly one successful workspace result",
    )
  }
  results[0]
}

///|
async fn read_document(path : String) -> Json {
  let data = @fs.read_file(path)
  let docs = @yaml.Yaml::load_from_string(data.text())
  guard docs.length() == 1 else {
    raise AdapterError("orca.yaml must contain exactly one YAML document")
  }
  docs[0].to_json()
}

///|
async fn notify(stage : String) -> Unit {
  progress_message(stage + ": running…")
  save_diagnostic(stage, "started")
}

///|
async fn create_state(pinned_commit? : String) -> Json {
  create_recording.attempt += 1
  create_recording.phase = "input-validation"
  save_diagnostic("create-input", "received", source=Inputs)
  let mut attempt_complete = false
///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
) -> Unit {
  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    return
  }
  try {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      return
    }
    if @fs.exists(path) && @fs.file_size(path) > 262144L {
      @fs.remove(path)
    }
    let event : Json = {
      "stage": stage,
      "status": status,
      "time": @env.now().to_string(),
      "runId": recording_run_id,
      "adapterVersion": version,
    }
    if create_recording.attempt > 0 {
      set_field(
        event,
        "createAttempt",
        Json::number(create_recording.attempt.to_double()),
      )
      set_field(event, "createPhase", Json::string(create_recording.phase))
    }
    if source is Some(evidence) {
      set_field(event, "source", evidence.to_json())
    }
    if os_errno is Some(code) && code > 0 && code < 4096 {
      set_field(event, "osErrno", Json::number(code.to_double()))
    }
    if exit_code is Some(code) {
      set_field(event, "exitCode", Json::number(code.to_double()))
    }
    for pair in [("errorType", error_type), ("phase", phase)] {
      if pair.1 is Some(text) {
        set_field(event, pair.0, Json::string(text))
      }
    }
    if duration_ms is Some(value) {
      set_field(event, "durationMs", Json::number(value))
    }
    if attempt is Some(value) {
      set_field(event, "attempt", Json::number(value.to_double()))
    }
    if retry_delay_ms is Some(value) {
      set_field(event, "retryDelayMs", Json::number(value.to_double()))
    }
    @fs.write_file(
      path,
      event.stringify() + "\n",
      permission=0o600,
      append=true,
      create_mode=@fs.OpenOrCreate,
    )
  } catch {
    _ => ()
  }
}

///|
let recording_run_id : String = @env.now().to_string()

///|
fn process_error_type(output : String) -> String {
  let text = output.to_lower()
  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    "memory_exhausted"
  } else if text.contains("no space left on device") {
    "disk_exhausted"
  } else if text.contains("address already in use") ||
    text.contains("addrinuse") {
    "address_in_use"
  } else if text.contains("permission denied (publickey") ||
    text.contains("authentication failed") {
    "authentication_failed"
  } else if text.contains("host key verification failed") {
    "host_key_failed"
  } else if text.contains("connection refused") {
    "connection_refused"
  } else if text.contains("connection timed out") ||
    text.contains("operation timed out") {
    "connection_timeout"
  } else if text.contains("could not resolve hostname") {
    "name_resolution"
  } else if text.contains("controlsocket") || text.contains("control socket") {
    "control_socket"
  } else if text.contains("build_vm:") {
    "vm_boot"
  } else if text.contains("create microsandbox vm") && text.contains("network:") {
    "vm_network"
  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
    "vm_mount"
  } else if text.contains("ensure microsandbox final image") ||
    text.contains("prepare microsandbox final image") {
    "vm_image"
  } else if text.contains("create microsandbox vm") {
    "vm_create"
  } else if text.contains("start microsandbox vm") {
    "vm_start"
  } else if text.contains("no such file or directory") ||
    text.contains("not found") {
    "missing_resource"
  } else if text.contains("permission denied") {
    "permission_denied"
  } else if text.contains("database is locked") ||
    text.contains("database locked") {
    "database_locked"
  } else if text.contains("too many open files") {
    "file_limit"
  } else {
    "process_exit"
  }
}

///|
async fn tunnel_errors(reader : @process.ReadFromProcess) -> String {
  defer reader.close()
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(bytes) {
    // Decode chunks lossy: arbitrary process stderr need not be valid UTF-8.
    let chunk = @utf8.decode_lossy(bytes)
    tail += chunk
    if tail.length() > 8192 {
      tail = tail[tail.length() - 8192:].to_owned()
    }
  }
  process_error_type(tail)
}

///|
priv struct CreateRecording {
  mut attempt : Int32
  mut phase : String
}

///|
let create_recording : CreateRecording = {
  attempt: 0,
  phase: "input-validation",
}

///|
priv enum CreateEvidence {
  Inputs
  Configuration(String, String, String?)
  Request(String, Bool)
  Lookup(String)
  Selection(String, String, String?, String, String)
  Clone(String?, String, Array[String], String?)
  TaskHeadRetry(String)
  AcquiredCommit(String)
  Checkout(String, String, Bool)
}

///|
priv enum DiagnosticValueKind {
  Identity
  Workspace
  RefName
  Commit
}
# orca-env-devsy

Use a Devsy devcontainer as an Orca per-workspace environment. Orca owns the
worktree and agent; Devsy owns provisioning and providers. This adapter connects
their recipe and lifecycle contracts.

## Install

```sh
mise use github:atty303/orca-env-devsy
```

## Prerequisites

| Where | Required commands |
| --- | --- |
| Host | Devsy 1.23.2+ (`devsy`), Git (`git`), OpenSSH (`ssh`), a POSIX shell and `env` supporting `-u` |
| Devcontainer, both connections | Git, `stat` supporting `-f -c %T`, `sleep`, and a POSIX-compatible SSH command shell |
| Devcontainer, Server connection | Linux x86_64/arm64; `curl`, `uname`, `mkdir`, `mktemp`, `chmod`, `mv`, `rm`; [official Orca Linux runtime libraries](https://github.com/stablyai/orca/blob/v1.4.224/config/docker/cli-launch-contract/Dockerfile) |
| Host, Codex addon refresh | Codex (`codex`) with managed ChatGPT file authentication |
| Devcontainer, Codex addon enabled | `grep`, `cat`, `sha256sum`, `mkdir`, `mktemp`, `mv`, `rm` |

Host binaries support macOS 13+ on Apple Silicon and Linux with glibc 2.31+
on x86_64/arm64.

Prepare your Devsy provider and context before using the recipe. The adapter
installs Orca on the Server target; it does not install system packages or
register providers. SSH connections use the Devsy-generated SSH configuration
for host-key and agent-forwarding options.

## Configure

Add settings to the repository's original `orca.yaml`:

```yaml
devsy:
  connection: orca-server
  profile: cloud
  profiles:
    cloud:
      context: "${DEVSY_CONTEXT?}"
      upArgs: ["--provider", "example-provider"]
    local:
      upArgs: ["--provider", "docker"]

environmentRecipes:
  - id: cloud-server
    name: Cloud Server
    checkoutMode: orca-worktree
    devsy:
      buildRef: main
    create: orca-env-devsy create
    resume: orca-env-devsy resume
    suspend: orca-env-devsy suspend
    destroy: orca-env-devsy destroy
  - id: local-ssh
    name: Local SSH
    checkoutMode: provisioned-root
    devsy:
      profile: local
      connection: ssh
    create: orca-env-devsy create
    resume: orca-env-devsy resume
    suspend: orca-env-devsy suspend
    destroy: orca-env-devsy destroy
```

Settings apply in common → one selected profile → recipe order. `upArgs` append
in that order without splitting their elements. `${VAR}` expands to empty when
undefined; `${VAR?}` requires the variable to be defined, allowing an empty
value. There is no shell evaluation.

`buildRef` selects the entire build checkout, including lifecycle commands. It is
required for `orca-worktree`; choose the branch used as Orca's usual base, such
as `main`. For devcontainer development, select the build branch independently
of Orca's worktree base. `provisioned-root` may omit it to build directly from
Orca's supplied start ref and commit. The resulting `userData.buildRef` and
`userData.buildCommit` identify the build source. Lifecycle operations use saved
settings; editing YAML affects new workspaces only.

After a host reboot, run `orca-env-devsy reconnect` to restore enabled SSH
connections and Server tunnels saved by this adapter under `${XDG_STATE_HOME:-$HOME/.local/state}`.
No workspace selection or receipt is required. Stopped workspaces are skipped;
the adapter does not run workspace-up or start the remote Server. To restore one
connection and emit recipe JSON, use `orca-env-devsy reconnect --receipt` with
its saved Orca lifecycle payload on stdin. Existing environments become available
for bulk recovery on their next resume or receipt-based reconnect.

Enable the optional Codex credential handoff with `devsy.addons.codexAuth: true`.
At create/resume it refreshes file-backed ChatGPT authentication through the host
Codex CLI when less than seven days remain, then transfers only access/account
data. Refresh failure warns and allows a still-valid token to be forwarded;
expired or unavailable authentication warns and continues without delivery.
Remote manually managed authentication is preserved. There is no ongoing
background authentication synchronization.

See [configuration and contracts](docs/contracts.md) for the supported fields,
connection constraints and local diagnostic controls.
